<script setup>
import ContextPageHeading from '@/shared/presentation/components/ContextPageHeading.vue'
import { useRecordNavigation } from '@/shared/presentation/composables/useRecordNavigation'
import { computed,ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { useSafeLabDemoStore } from '@/shared/application/stores/demo.store'
import { useAuthStore } from '@/boundedcontext/identityaccess/application/stores/auth.store'
const demo=useSafeLabDemoStore(),auth=useAuthStore(),{t,locale}=useI18n()
const billing=computed(()=>auth.isOrganizationAdmin?demo.subscriptionFor(auth.currentUser?.organizationId):null)
const documents=computed(()=>billing.value?.invoices||[])
const selected=ref(null),filter=ref('all')
const visibleDocs=computed(()=>filter.value==='all'?documents.value:documents.value.filter(d=>d.status===filter.value))
const fmtMoney=(n)=>new Intl.NumberFormat(locale.value==='es'?'es-PE':'en-US',{style:'currency',currency:'PEN'}).format(n||0)
const fmtDate=(value)=>value?new Date(value+'T12:00:00').toLocaleDateString(locale.value==='es'?'es-PE':'en-US',{year:'numeric',month:'short',day:'numeric'}):'—'
const { openRecords } = useRecordNavigation()
</script>
<template>
  <section class="page billing-page"><div class="page-hero compact"><ContextPageHeading :description="t('billing.description')" /></div>
<div class="page-toolbar"><RouterLink to="/userprofiles/my-profile" class="btn"><i class="pi pi-arrow-left"></i> {{t('billing.backProfile')}}</RouterLink></div>
    <template v-if="billing">
      <div class="grid-4"><article class="kpi-card"><span class="kpi-copy"><span>{{t('billing.plan')}}</span><strong class="plan-name">{{billing.plan}}</strong><small>{{t('billing.planActive')}}</small></span></article><article class="kpi-card"><span class="kpi-copy"><span>{{t('billing.status')}}</span><strong>{{t(`platformUi.state_${billing.status}`)}}</strong><small>{{t('billing.planActive')}}</small></span></article><article class="kpi-card"><span class="kpi-copy"><span>{{t('billing.monthly')}}</span><strong>{{fmtMoney(billing.monthlyCost)}}</strong><small>{{t('billing.taxIncluded')}}</small></span></article><article class="kpi-card"><span class="kpi-copy"><span>{{t('billing.nextRenewal')}}</span><strong>{{fmtDate(billing.renewalDate)}}</strong><small>{{t('billing.nextDue')}}</small></span></article></div>
      <div class="grid-2"><article class="record-summary-card card" role="link" tabindex="0" aria-label="invoices" @click="openRecords('subscriptionbilling','invoices',$event)" @keydown.enter.self.prevent="openRecords('subscriptionbilling','invoices')" @keydown.space.self.prevent="openRecords('subscriptionbilling','invoices')"><div class="card-header"><div><p class="eyebrow">{{t('billing.upcoming')}}</p><h2>{{t('billing.nextInvoice')}}</h2></div><span class="status-pill warning">{{t('billing.upcomingStatus')}}</span></div><div v-if="documents.find(d=>d.status==='upcoming')" class="bill-card" @click.stop="selected=documents.find(d=>d.status==='upcoming')"><div><span>{{t('billing.receipt')}}</span><strong>{{documents.find(d=>d.status==='upcoming').number}}</strong></div><div><span>{{t('billing.amount')}}</span><strong>{{fmtMoney(documents.find(d=>d.status==='upcoming').amount)}}</strong></div><div><span>{{t('billing.due')}}</span><strong>{{fmtDate(documents.find(d=>d.status==='upcoming').dueDate)}}</strong></div><span class="view-prompt">{{t('billing.tapDetails')}} <i class="pi pi-arrow-right"></i></span></div></article><article class="record-summary-card card" role="link" tabindex="0" aria-label="invoices" @click="openRecords('subscriptionbilling','invoices',$event)" @keydown.enter.self.prevent="openRecords('subscriptionbilling','invoices')" @keydown.space.self.prevent="openRecords('subscriptionbilling','invoices')"><div class="card-header"><div><p class="eyebrow">{{t('billing.paymentHistory')}}</p><h2>{{t('billing.paidReceipts')}}</h2></div></div><div class="item-list"><button v-for="doc in documents.filter(d=>d.status==='paid')" :key="doc.id" class="list-row bill-button" type="button" @click="selected=doc"><span><strong>{{doc.number}}</strong><small>{{fmtDate(doc.date)}}</small></span><span><strong>{{fmtMoney(doc.amount)}}</strong><small class="status-pill success">{{t('billing.paid')}}</small></span><i class="pi pi-chevron-right"></i></button></div></article></div>
      <article class="card"><div class="card-header"><div><p class="eyebrow">{{t('billing.history')}}</p><h2>{{t('billing.allDocuments')}}</h2></div><div class="actions"><button v-for="key in ['all','paid','upcoming']" :key="key" type="button" :class="['btn','small',filter===key?'primary':'']" @click="filter=key">{{t(`billing.filter_${key}`)}}</button></div></div><div class="table-scroll"><table class="responsive-table"><thead><tr><th>{{t('billing.receipt')}}</th><th>{{t('billing.date')}}</th><th>{{t('billing.amount')}}</th><th>{{t('billing.status')}}</th><th></th></tr></thead><tbody><tr v-for="doc in visibleDocs" :key="doc.id"><td>{{doc.number}}</td><td>{{fmtDate(doc.date)}}</td><td>{{fmtMoney(doc.amount)}}</td><td><span :class="['status-pill',doc.status==='paid'?'success':'warning']">{{t(`billing.${doc.status==='paid'?'paid':'upcomingStatus'}`)}}</span></td><td><button class="btn small" @click="selected=doc">{{t('billing.details')}}</button></td></tr></tbody></table></div></article>
    </template><article v-else class="card"><h2>{{t('billing.noSubscription')}}</h2><p>{{t('billing.noData')}}</p></article>
    <div v-if="selected" class="modal-backdrop" @click.self="selected=null"><article class="card modal-card medium" role="dialog" aria-modal="true" :aria-label="t('billing.details')"><header class="modal-header"><div><p class="eyebrow">{{t('billing.details')}}</p><h2>{{selected.number}}</h2></div><button class="icon-action" type="button" :aria-label="t('profile.cancel')" @click="selected=null"><i class="pi pi-times"></i></button></header><div class="pair-grid"><div v-for="[label,value] in [[t('billing.receipt'),selected.number],[t('billing.status'),t(selected.status==='paid'?'billing.paid':'billing.upcomingStatus')],[t('billing.date'),fmtDate(selected.date)],[t('billing.due'),fmtDate(selected.dueDate)],[t('billing.subtotal'),fmtMoney(selected.subtotal)],[t('billing.tax'),fmtMoney(selected.tax)],[t('billing.total'),fmtMoney(selected.amount)],[t('billing.method'),selected.method||'—'],[t('billing.reference'),selected.reference||'—']]" :key="label" class="pair-box"><span>{{label}}</span><strong>{{value}}</strong></div></div><div class="modal-footer"><button class="btn primary" type="button" @click="selected=null">{{t('billing.close')}}</button></div></article></div>
  </section>
</template>
<style scoped>
.plan-name{font-size:1.1rem!important;line-height:1.5!important;white-space:normal}.kpi-card{min-width:0}.kpi-copy{min-width:0}.bill-card{border:1px solid var(--border);background:var(--surface-soft);border-radius:18px;padding:18px;display:grid;gap:15px;cursor:pointer}.bill-card div{display:flex;justify-content:space-between;flex-wrap:wrap;gap:10px}.bill-card span{color:var(--muted)}.bill-card strong{color:var(--text);overflow-wrap:anywhere}.view-prompt{color:var(--primary)!important;font-weight:850}.bill-button{width:100%;border:1px solid var(--border);cursor:pointer;text-align:left;color:var(--text);grid-template-columns:minmax(0,1fr) auto 16px}.bill-button:hover{border-color:var(--primary)}.bill-button span{min-width:0}.bill-button span strong{overflow-wrap:anywhere}.table-scroll{overflow:auto;width:100%}.responsive-table{min-width:630px}.pair-box strong{overflow-wrap:anywhere}.modal-card{max-width:680px}.modal-card h2{overflow-wrap:anywhere}
</style>
